/*
 * A177217  The products k of two distinct primes such that 2*k-1, 4*k-3,
 *          8*k-7, 16*k-15, 32*k-31, 64*k-63, 128*k-127 and 256*k-255 are also
 *          products of two distinct primes.
 * https://oeis.org/A177217
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth integer k satisfying that k and 2k‑1, 4k‑3,
 *            8k‑7, 16k‑15, 32k‑31, 64k‑63, 128k‑127, 256k‑255 are all
 *            products of two distinct primes. The sequence is generated by an
 *            incremental search
 * Range:     u8 none, u16 n <= 5, u32 n <= 30, u64 n <= 30, u128 n <= 30,
 *            big any n
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/factor_u64.h"

static inline bool is_product_two_distinct_primes(uint64_t n)
{
    uint64_t primes[32];
    uint64_t exps[32];
    size_t cnt;
    factor_u64(n, primes, exps, &cnt);
    return (cnt == 2) && (exps[0] == 1) && (exps[1] == 1);
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset is 1, a(1) is the first term   */
    static seq_t *terms = NULL;    /* cache of found terms   */
    static size_t len   = 0;        /* number of terms cached */
    static size_t cap   = 0;        /* current cache capacity */
    static uint64_t candidate = 6;  /* first product of two distinct primes */

    /* grow cache if needed */
    if (cap == 0) {
        cap = 64;
        terms = (seq_t *)malloc(cap * sizeof(seq_t));
    }
    while (len < (size_t)n) {
        /* Find next candidate that is a product of two distinct primes.   */
        while (!is_product_two_distinct_primes(candidate))
            ++candidate;

        /* Check the eight derived numbers. */
        const uint64_t mult[8] = {2,4,8,16,32,64,128,256};
        const uint64_t sub [8] = {1,3,7,15,31,63,127,255};
        bool ok = true;
        for (int i = 0; i < 8 && ok; ++i) {
            unsigned __int128 prod = (unsigned __int128)mult[i] * candidate;
            uint64_t t = (uint64_t)(prod - sub[i]);   /* safe cast: prod<2^128 */
            if (!is_product_two_distinct_primes(t))
                ok = false;
        }

        if (ok) {
            /* Append to cache. Grow if necessary. */
            if (len == cap) {
                cap *= 2;
                terms = (seq_t *)realloc(terms, cap * sizeof(seq_t));
            }
            terms[len++] = (seq_t)candidate;
        }

        /* Move to next candidate. */
        ++candidate;
    }

    return terms[n - 1];
}
